+import type { SignedSessionToken } from "./session-store.ts";
+
+export interface EdgeSessionValidator {
+  validateToken(token: SignedSessionToken): boolean;
+  recordRevocation(sessionId: string): void;
+  setRevocationFetchFn(fn: () => Promise<string[]>): void;
+}
+
+export const createEdgeSessionValidator = (): EdgeSessionValidator => {
+  const revokedSessions = new Set<string>();
+  const REVOCATION_TTL_MS = 65_000; // 65 seconds to cover the 60-second SLA
+  const revocationTimestamps = new Map<string, number>();
+  let revocationFetchFn: (() => Promise<string[]>) | null = null;
+
+  const validateToken = (token: SignedSessionToken): boolean => {
+    // Check if session is in local revocation cache
+    if (revokedSessions.has(token.sessionId)) {
+      return false;
+    }
+
+    return true;
+  };
+
+  const recordRevocation = (sessionId: string): void => {
+    const now = Date.now();
+    revokedSessions.add(sessionId);
+    revocationTimestamps.set(sessionId, now);
+
+    // Auto-expire from revocation cache after TTL
+    setTimeout(() => {
+      revokedSessions.delete(sessionId);
+      revocationTimestamps.delete(sessionId);
+    }, REVOCATION_TTL_MS);
+  };
+
+  const setRevocationFetchFn = (
+    fn: () => Promise<string[]>,
+  ): void => {
+    revocationFetchFn = fn;
+
+    // Periodically sync revocations from the main service
+    // This ensures that if a revocation broadcast was missed, we eventually learn about it
+    setInterval(async () => {
+      try {
+        const revokedIds = await fn();
+        for (const id of revokedIds) {
+          if (!revokedSessions.has(id)) {
+            recordRevocation(id);
+          }
+        }
+      } catch {
+        // Silently fail if fetch fails — we'll retry on next interval
+      }
+    }, 10_000); // Check every 10 seconds
+  };
+
+  return {
+    validateToken,
+    recordRevocation,
+    setRevocationFetchFn,
+  };
+};
