+import { pool } from "./pool.ts";
+
+// Maintains a window of recently revoked sessions for edge workers to query
+// without hitting the database directly
+const recentRevocations = new Map<string, number>();
+const REVOCATION_WINDOW_MS = 65_000; // Keep revocations visible for 65 seconds
+
+export const trackRevocation = (sessionId: string): void => {
+  const now = Date.now();
+  recentRevocations.set(sessionId, now);
+
+  // Auto-expire from memory after window passes
+  setTimeout(() => {
+    recentRevocations.delete(sessionId);
+  }, REVOCATION_WINDOW_MS);
+};
+
+export const getRecentlyRevokedSessions = async (): Promise<string[]> => {
+  // Return all sessions revoked in the last REVOCATION_WINDOW_MS
+  const now = Date.now();
+  const cutoff = now - REVOCATION_WINDOW_MS;
+
+  const result = await pool.query(
+    "SELECT id FROM sessions WHERE revoked_at IS NOT NULL AND revoked_at > to_timestamp($1/1000.0)",
+    [cutoff],
+  );
+
+  const dbRevoked = result.rows.map((row: { id: string }) => row.id);
+  const memRevoked = Array.from(recentRevocations.keys());
+
+  // Combine both sources and deduplicate
+  return Array.from(new Set([...dbRevoked, ...memRevoked]));
+};
