+  const expectedSignature = createSignature(
+    token.sessionId,
+    token.userId,
+    token.timestamp,
+  );
+
+  if (expectedSignature !== token.signature) {
+    return false;
+  }
+
+  if (revokedSessions.has(token.sessionId)) {
+    return false;
+  }
+
+  return true;
